@js:
var html = String(result);
var m = html.match(/"url_next":"([^"]*)"/);
var pUrl = m ? m[1].replace(/\\\//g, '/') : '';
if (!pUrl || pUrl.indexOf('http') !== 0) {
    var p = html.match(/player_aaaa=(\{[\s\S]*?\})\s*<\/script>/) || html.match(/player_aaaa=(\{[\s\S]*?\})/);
    if (p) {
        try {
            var d = JSON.parse(p[1]);
            pUrl = (d.url || '').replace(/\\\//g, '/');
        } catch (e) {
            var u = p[1].match(/"url":"([^"]+)"/);
            pUrl = u ? u[1].replace(/\\\//g, '/') : '';
        }
    }
}
if (pUrl && (pUrl.indexOf('.m3u8') > 0 || pUrl.indexOf('.mp4') > 0)) {
    pUrl;
} else if (pUrl) {
    try { java.startBrowserAwait(pUrl, title); } catch (err) {}
    '请刷新查看内容';
} else {
    '请刷新查看内容';
}
